<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($pageTitle)?></title><link rel="stylesheet" href="assets/css/base.css"><link rel="stylesheet" href="assets/css/components/header.css"><link rel="stylesheet" href="assets/css/components/footer.css"><link rel="stylesheet" href="assets/css/pages/portal.css"></head><body><?php include TEMPLATES_PATH.'/partials/header.php';?><main class="portal-page"><div class="portal-head"><h1>پروفایل من</h1></div><?php if(isset($_GET['saved'])):?><div class="portal-alert">اطلاعات پروفایل ذخیره شد.</div><?php endif;?><div class="portal-grid"><section class="portal-card"><h2>اطلاعات شخصی</h2><form class="portal-form" method="post" action="profile-save.php"><label>نام و نام خانوادگی<input name="full_name" value="<?=htmlspecialchars((string)($user['full_name']??''))?>"></label><label>شماره موبایل<input value="<?=htmlspecialchars((string)($user['phone']??''))?>" disabled></label><label>ایمیل<input type="email" name="email" value="<?=htmlspecialchars((string)($user['email']??''))?>"></label><label>تاریخ تولد<input type="date" name="birth_date" value="<?=htmlspecialchars((string)($user['birth_date']??''))?>"></label><label>شهر<input name="city" value="<?=htmlspecialchars((string)($user['city']??''))?>"></label><label>هفته بارداری<input type="number" min="1" max="40" name="pregnancy_week" value="<?=htmlspecialchars((string)($user['pregnancy_week']??''))?>"></label><button>ذخیره تغییرات</button></form></section><section class="portal-card"><h2>کودکان من</h2><?php foreach($children as $c):?><p><a href="child.php?id=<?=(int)$c['id']?>"><?=htmlspecialchars($c['full_name'])?></a> <span class="portal-muted"><?=htmlspecialchars($c['birth_date'])?></span></p><?php endforeach;?><?php if(!$children):?><p class="portal-muted">هنوز کودکی ثبت نشده.</p><?php endif;?><a class="portal-link-btn" href="children.php">مدیریت کودکان</a></section><section class="portal-card"><h2>نوبت‌های پزشک</h2><?php foreach(array_slice($appointments,0,3) as $a):?><p><?=htmlspecialchars($a['doctor_name'])?> — <?=htmlspecialchars($a['scheduled_at'])?></p><?php endforeach;?><?php if(!$appointments):?><p class="portal-muted">نوبتی ثبت نشده.</p><?php endif;?><a class="portal-link-btn" href="appointments.php">همه نوبت‌ها</a></section></div></main><?php include TEMPLATES_PATH.'/partials/footer.php';?><script src="assets/js/components/header.js"></script></body></html>
